import { LitElement, html, css } from 'https://cdn.skypack.dev/lit';

class DmoButton extends LitElement {
  static styles = css`
    button {
      background-color: blue;
      color: white;
      font-size: 16px;
      border: none;
      border-radius: 5px;
      padding: 10px 20px;
      cursor: pointer;
      transition: background-color 0.3s;
    }
    button:hover {
      background-color: darkblue;
    }
  `;

  render() {
    return html`<button>Click me</button>`;
  }
}

customElements.define('dmo-button', DmoButton);
